    from collections import Counter
    n = Counter(c for row in grid for c in row)
    dot = n.most_common()[-1][0]
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(H):
        cols = [c for c in range(W) if grid[r][c] == dot]
        if len(cols) >= 2:
