def count_components(grid, color):
    """Count number of connected components for a given color."""
    if not grid or not grid[0]:
        return 0
    H, W = len(grid), len(grid[0])
    visited = [[False] * W for _ in range(H)]
    components = 0

    from collections import deque
    def is_connected(r, c, target_color):
        """Check if cell (r, c) belongs to same component as source."""
        to_visit = deque([(r, c)])
        target_visited = [[False] * W for _ in range(H)]
        target_visited[r][c] = True

        while to_visit:
            cr, cc = to_visit.popleft()
            if grid[cr][cc] == target_color and not target_visited[cr][cc]:
                target_visited[cr][cc] = True
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == target_color:
                        if not target_visited[nr][nc]:
                            target_visited[nr][nc] = True
                            to_visit.append((nr, nc))
        return any(target_visited[r][c])

    # Count exclusive components for each cell
    exclusive_comps = {}
    for i in range(H):
        for j in range(W):
            if grid[i][j] == color:
                key = f"({i},{j})"
                if key not in exclusive_comps:
                    exclusive_comps[key] = is_connected(i, j, color)

    # Count how many distinct components exist (cells that are part of a unique component)
    return exclusive_comps

def transform_v2(grid):
