                    # BFS
                    queue = [(i, j)]
                    visited.add((i, j))
                    while queue:
                        cr, cc = queue.pop(0)
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                    components += 1
        color_components[color] = components

    print("Component counts per color:", color_components)

